  "ui.plugin.mcpHowClients": "配置文件位置：Claude Code＝项目根 .mcp.json；Cursor＝.cursor/mcp.json（或设置里的 MCP 面板）；Trae＝MCP 设置面板；Codex / Cline＝各自 MCP 配置；Claude Desktop＝claude_desktop_config.json",
