  "ui.plugin.mcpPromptHead": "请把「恒烈CTF编码工具箱」接入你的 MCP：",
  "ui.plugin.mcpPromptDirFilled": "1) 它在本机的安装目录：{0}",
  "ui.plugin.mcpPromptDirAuto": "1) 请先在本机定位它的安装目录（特征：通用点我启动.py 与 mcp/server.mjs 在同一目录；找不到或多份时问我）",
  "ui.plugin.mcpPromptRest": "2) 在该目录运行 `py 通用点我启动.py --mcp-config`，把输出里的 mcpServers JSON 原样写入你的 MCP 配置（.mcp.json / claude_desktop_config.json 等），重启后应出现 6 个 ebctf_* 工具。\n3) 这是本地 stdio 服务，纯本地、零外发。\n工具速查：ebctf_list_categories 列全部分类｜ebctf_list_ops 按关键词/分类列算法｜ebctf_op_schema 查参数 schema｜ebctf_detect 智能识别编码｜ebctf_run_op 跑指定算法｜ebctf_magic_decode 一键智能解码（支持多层链式）。",

