  "ui.rand.testOkBytes": "连接成功，取回 {0} 字节",
  "ui.rand.mouseAux": "附加鼠标熵",
  "ui.rand.mouseAuxDesc": "在弹窗里晃动鼠标采集本地熵，叠加到当前档位（只增不减，结果不弱于原档）。用于不受信任的系统：不让系统随机源成为单点。",
  "ui.rand.mouseStatus": "鼠标熵",
