  "ui.rand.mouseCollect": "采集鼠标随机性",
  "ui.rand.mouseRecollect": "重新采集",
  "ui.rand.mouseTitle": "采集鼠标随机性",
  "ui.rand.mouseHint": "在下方区域快速晃动鼠标（或手指滑动），采集足够熵后点「完成」。",
  "ui.rand.mousePadHint": "在此区域晃动鼠标…",
